import '../../models/digital_athlete.dart';

/// Single structured proactive insight generated by the Digital Athlete Intelligence engine.
class AthleteInsightItem {
  final String id;
  final String
  category; // 'strength', 'recovery', 'consistency', 'biomechanics', 'nutrition'
  final String title;
  final String description;
  final String recommendation;
  final double significanceScore; // 0.0 to 1.0
  final DateTime createdAt;

  const AthleteInsightItem({
    required this.id,
    required this.category,
    required this.title,
    required this.description,
    required this.recommendation,
    required this.significanceScore,
    required this.createdAt,
  });

  factory AthleteInsightItem.fromJson(Map<String, dynamic> json) {
    return AthleteInsightItem(
      id:
          json['id']?.toString() ??
          'ins_${DateTime.now().millisecondsSinceEpoch}',
      category: json['category']?.toString() ?? 'strength',
      title: json['title']?.toString() ?? '',
      description: json['description']?.toString() ?? '',
      recommendation: json['recommendation']?.toString() ?? '',
      significanceScore:
          (json['significance_score'] as num?)?.toDouble() ?? 0.85,
      createdAt: json['created_at'] != null
          ? DateTime.tryParse(json['created_at'].toString()) ?? DateTime.now()
          : DateTime.now(),
    );
  }

  Map<String, dynamic> toJson() => {
    'id': id,
    'category': category,
    'title': title,
    'description': description,
    'recommendation': recommendation,
    'significance_score': significanceScore,
    'created_at': createdAt.toIso8601String(),
  };
}

/// Service continuously synthesizing longitudinal multi-domain data from [DigitalAthlete]
/// into actionable, proactive coaching insights.
class InsightGenerationService {
  static InsightGenerationService? _instance;
  static InsightGenerationService get instance =>
      _instance ??= InsightGenerationService();

  /// Generates proactive weekly insights from the athlete's digital twin.
  List<AthleteInsightItem> generateWeeklyInsights(DigitalAthlete athlete) {
    final List<AthleteInsightItem> insights = [];
    final now = DateTime.now();

    // 1. Strength Insight
    final squat1RM = athlete.strengthProfile.estimated1RM['Squat'] ?? 130.0;
    final squatVelocity = athlete.strengthProfile.progressionVelocityPercentage;
    insights.add(
      AthleteInsightItem(
        id: 'ins_str_${now.millisecondsSinceEpoch}',
        category: 'strength',
        title: 'Squat Strength Progression',
        description:
            'Your squat improved ${squatVelocity.round()}% this month (Estimated 1RM: ${squat1RM.round()} kg).',
        recommendation:
            'Continue adding 2.5 kg micro-plates to compound working sets while preserving depth.',
        significanceScore: 0.94,
        createdAt: now,
      ),
    );

    // 2. Recovery & Fatigue Insight
    if (athlete.recoveryProfile.averageRecoveryScore < 80.0 ||
        athlete.recoveryProfile.fatigueSensitivity == 'high') {
      insights.add(
        AthleteInsightItem(
          id: 'ins_rec_${now.millisecondsSinceEpoch}',
          category: 'recovery',
          title: 'Consecutive Session Fatigue Trigger',
          description:
              'Your recovery drops after consecutive heavy sessions (Average HRV: ${athlete.recoveryProfile.hrvAverage.round()} ms).',
          recommendation:
              'Incorporate a dedicated active recovery or mobility day between heavy compound workouts.',
          significanceScore: 0.90,
          createdAt: now,
        ),
      );
    } else {
      insights.add(
        AthleteInsightItem(
          id: 'ins_rec_${now.millisecondsSinceEpoch}',
          category: 'recovery',
          title: 'High Autonomic Resilience',
          description:
              'Your recovery readiness is primed at ${athlete.recoveryProfile.averageRecoveryScore.round()}/100 across 7+ hours sleep.',
          recommendation:
              'Athlete capacity is optimal for high-intensity progressive overload.',
          significanceScore: 0.88,
          createdAt: now,
        ),
      );
    }

    // 3. Cadence & Consistency Insight
    final preferredTime = athlete.behaviorProfile.preferredWorkoutTime;
    final consistency = athlete.behaviorProfile.consistencyScore;
    insights.add(
      AthleteInsightItem(
        id: 'ins_con_${now.millisecondsSinceEpoch}',
        category: 'consistency',
        title: 'Circadian Peak Momentum',
        description:
            'You are most consistent with $preferredTime workouts, maintaining a ${consistency.round()}% completion rate.',
        recommendation:
            'Schedule your heaviest primary lifts during your $preferredTime window for maximum motor unit recruitment.',
        significanceScore: 0.92,
        createdAt: now,
      ),
    );

    // 4. Biomechanics Insight
    if (athlete.biomechanicsWeaknesses.isNotEmpty) {
      final weakness = athlete.biomechanicsWeaknesses.first;
      insights.add(
        AthleteInsightItem(
          id: 'ins_bio_${now.millisecondsSinceEpoch}',
          category: 'biomechanics',
          title: 'Technique Reinforcement',
          description: 'Movement tracking flagged: $weakness.',
          recommendation:
              'Perform band-resisted warm-up sets to activate stabilizer musculature before top working sets.',
          significanceScore: 0.89,
          createdAt: now,
        ),
      );
    }

    return insights;
  }
}
